--
-- 21 new cross_references rows at tier_required=''extras'' (Library
-- tier, $4.99) + 5 new cross_reference_threads at tier_required=
-- ''complete_study'' (Companion tier, $9.99). The tier split honors
-- the chapter-end-card architecture established at S146 and prior:
-- Layer 1 (per-verse cross-refs) visible to Library readers; Layer 2
-- (framework thread callouts with summary_md + member_notes) gated at
-- Companion. Every member-note passes the 12 Red Lines and the
-- 12-point editorial checklist. The seed-mechanism per framework-
-- deep''s *Paternal Seed and the Marriage-Covenant Absorption* section
-- + Red Line #7 augmentation does not surface in Matt 21 as a per-
-- verse application (no foreign-origin individuals or marriage-
-- covenant cases in the chapter); BUT Red Line #11''s ingathering-of-
-- the-paternal-blood-remnant-of-all-twelve-tribes architecture is
-- load-bearing at v.43''s *given to a nation bringing forth the fruits
-- thereof* and is the spine of Thread 5 — the *nation* (Greek *ethnos*
-- singular) is the gathered-bringing-forth-fruit-remnant of the
-- twelve-tribes, NOT the categorical-church-replacing-Yashar''el
-- (Israel).
-- Hebrew names with internal apostrophes (Yashar''el, Ya''aqov,
-- Yechezk''el, Yo''el, Sha''ul, Yo''akhim, King''s, Father''s,
-- Yahuah''s, Yochanan''s, Kefa''s, etc.) and English possessives
-- (wisdom-stream''s, leadership''s, Father''s, King''s, system''s,
-- etc.) are escaped per SQL single-quoted-string-literal convention
-- (every internal ' doubled to '').
--
-- Idempotent: ON CONFLICT DO NOTHING on every INSERT.
-- =====================================================================

\echo 'Session 155 — Matt 21 extras-tier cross-references migration starting...'
BEGIN;

-- Verse-lookup temp view. Mirrors the S154 view (renamed to _s155);
-- retained edition set for forward compatibility even though Matt 21
-- surfaces only canon + enoch + apocrypha + pseudepigrapha at S155.
CREATE TEMP VIEW _s155_xref_lookup AS
SELECT
    e.slug AS edition_slug,
    b.slug AS book_slug,
    c.chapter_number,
    v.verse_number,
    v.id AS verse_id
  FROM verses v
  JOIN chapters c ON v.chapter_id = c.id
  JOIN books    b ON c.book_id    = b.id
  JOIN editions e ON b.edition_id = e.id
 WHERE e.slug IN (
       'canon',
       'enoch',
       'jubilees',
       'jasher',
       'apocrypha',
       'apocrypha-charles-vol1',
       'pseudepigrapha',
       'adam-eve-conflict',
       'apocalypse-of-abraham',
       'ascension-isaiah',
       'sonnini-acts-29'
   );

-- ---------------------------------------------------------------------
-- Insert 21 extras-tier cross_references rows.
-- ---------------------------------------------------------------------
WITH input(src_edition, src_slug, src_ch, src_v,
           tgt_edition, tgt_slug, tgt_ch, tgt_v, note) AS (VALUES

  -- Thread 1: davidic-messianic-king-meek-on-the-foal-in-testaments-xii-and-2-maccabees
  ('canon', 'matthew', 21, 5, 'pseudepigrapha', 'testaments-xii', 38, 5,
   '*Then shall the sceptre of my kingdom shine forth ; and from your root shall arise a stem.* Testament of Yahudah (Judah) ch 15 v.5 (Charles vol 2''s flat-chapter scheme places Test. Yahudah ch 15 at ch 38 of the testaments-xii edition) names THE direct wisdom-stream verbal-anchor for the Davidic-Messianic-King substance the triumphal-entry walks-out at Matt 21:5. The framework reads the verse against Matt 21:5''s *behold, thy King cometh unto thee, meek, and sitting upon an ass.* The Tanakh-substance the King-walks-into is the prophet Zecharyah (Zechariah) 9:9 substance the Matthean signature-citation-formula attaches the entry-substance to; the Testaments of the XII Patriarchs'' substance at the dying-Yahudah''s blessing-of-his-sons names the same Messianic-King substance at the wisdom-stream-register — the sceptre-of-the-kingdom-shining-forth + the stem-arising-from-the-root substance the prophet Yeshayahu (Isaiah) 11:1 had-named at the Tanakh-Netser-Branch-substance. The wisdom-stream and the gospel cohere at the King-of-the-tribe-of-Yahudah substance the entry-substance walks-out at the historical-pivot the prophets and the patriarchs had-named the substance-of for centuries.'),

  ('canon', 'matthew', 21, 5, 'pseudepigrapha', 'testaments-xii', 38, 6,
   '*And from it shall grow up the rod of righteousness unto the Gentiles, To judge and to save all that call upon Yahuah (Lord).* Testament of Yahudah (Judah) ch 15 v.6 names the wisdom-stream articulation of the rod-of-righteousness substance the Messianic-King carries-out — the *judge and save all that call upon Yahuah* substance the framework reads carefully. The framework reads the verse against Matt 21:5''s King-coming-to-his-city substance. The substance the wisdom-stream names at *all that call upon Yahuah (Lord)* is the substance the King-walks at the marginalized-substance crying *Son of David* (Matt 9:27, 15:22, 20:30-31) now-walked-by-the-multitudes at the entry-substance; the *Gentiles* in the wisdom-stream-language carries the same wisdom-stream-convention as Paul''s-letters address — the substance is NOT the categorical-three-categories-nations-as-collective replacing-Yashar''el (Israel) but the substance of the scattered-seed-of-Yashar''el-living-as-Gentiles-among-the-nations per Red Line #7''s scattered-seed-coming-home substance + Red Line #11''s wild-olive-substance of the descendants-of-the-broken-off-who-hear-when-the-Shepherd-calls. The substance the wisdom-stream had named is the substance the gospel walks-out at the entry.'),

  ('canon', 'matthew', 21, 8, 'apocrypha', '2-maccabees', 10, 7,
   '*Therefore they bare branches, and fair boughs, and palms also, and sang psalms to him that had given them good success in cleansing his place.* 2 Maccabees 10:7 names THE direct wisdom-stream verbal-anchor for the branches-and-palms-and-psalms substance the multitudes walk at the entry. The framework reads the verse against Matt 21:8-9''s *and a very great multitude spread their garments in the way; others cut down branches from the trees, and strawed them in the way. And the multitudes that went before, and that followed, cried, saying, Hoshia-na (Hosanna) to the Son of David.* The 2 Maccabees passage names the substance the people had-walked at the Hanukkah-temple-rededication-substance — the branches + the palms + the psalms — at the immediately-prior wisdom-stream-historical-pivot. The multitudes at the entry walk the same substance — branches + palms + the Hallel-substance of Tehillim (Psalm) 118 — at the King''s-coming-into-the-city which the chapter immediately walks-into the Temple-cleansing-substance the Hanukkah-substance had-walked at the wisdom-stream-pivot. The wisdom-stream and the gospel cohere at the substance-of-the-people-walking-the-branches-and-the-psalms at the substance-of-the-Temple-being-cleansed.'),

  ('canon', 'matthew', 21, 9, 'apocrypha', 'ecclesiasticus', 36, 14,
   '*Fill Sion (Zion) with your unspeakable oracles, and your people with your glory.* Sirach (Ecclesiasticus) 36:14 names the wisdom-stream''s articulation of the prayer-for-the-glory-to-fill-Tsion (Zion) substance the King''s-arriving-at-Yerushalayim (Jerusalem) walks-out. The framework reads the verse against Matt 21:9''s *Hoshia-na (Hosanna) in the highest* + Matt 21:10''s *all the city was moved.* The wisdom-stream-substance the Sirach 36 passage walks is the prayer-for-the-Messianic-arrival-substance — *make the time short, remember the covenant* (v.8) + *gather all the tribes of Ya''aqov (Jacob) together* (v.11) + *fill Sion with your unspeakable oracles* (v.14) + *let your prophets be found faithful* (v.16). The substance the multitudes cry at the entry walks-into the substance the wisdom-stream-prayer had-named the Father-for: the glory-arriving-at-Tsion is the King-arriving-at-the-city. The Greek *eseisthē* the Matthean account uses for *all the city was moved* (v.10) carries the same root the Matt 27:51 earthquake-substance and the Matt 28:2 resurrection-earthquake-substance carry — the wisdom-stream had-named the Father''s-glory-arriving as the substance-that-fills-Tsion; the gospel walks the same substance at the King-arriving-into-the-shaken-city.'),

  -- Thread 2: temple-cleansing-and-the-maccabean-rededication-architecture
  ('canon', 'matthew', 21, 12, 'apocrypha', '1-maccabees', 4, 43,
   '*Who cleansed the sanctuary, and bare out the defiled stones into an unclean place.* 1 Maccabees 4:43 names the wisdom-stream''s direct verbal-anchor for the cleansing-of-the-sanctuary substance the King-walks-out at the temple-cleansing-pericope. The framework reads the verse against Matt 21:12''s *Yahusha (Jesus) went into the temple of Elohim (God), and cast out all them that sold and bought in the temple, and overthrew the tables of the moneychangers.* The historical-substance Yahudah-Maqqavi (Judas Maccabeus) had-walked at the wisdom-stream-pivot — the cleansing-of-the-sanctuary-after-the-Antiochene-defilement of the abomination-of-desolation — names the architectural-substance the King-walks-out at the Second-Temple-pivot against the Pharisaic-Sadducean monetization-substance that had-displaced the substance of prayer the Court-of-the-goyim was-meant-for. The substance the wisdom-stream names at the *bare out the defiled stones* substance is the same substance the King-walks at the *overthrew the tables of the moneychangers* substance — the system-substance''s-substance has-defiled the Father''s-house with the substance of the market, and the substance the King-walks-against is the same substance the wisdom-stream-pivot had-walked-against at the prior-substance.'),

  ('canon', 'matthew', 21, 12, 'apocrypha', '2-maccabees', 10, 3,
   '*And having cleansed the temple they made another altar, and striking stones they took fire out of them, and offered a sacrifice after two years, and set forth incense, and lights, and shewbread.* 2 Maccabees 10:3 names the wisdom-stream''s narration of the Hanukkah-cleansing-of-the-Temple substance — the cleansing-followed-by-the-restoration-of-the-sacrifice-the-incense-the-lights-the-shewbread substance the Father''s-house was-meant-for. The framework reads the verse against Matt 21:12''s temple-cleansing substance. The wisdom-stream-substance walks the cleansing-and-restoration architecture at the wisdom-stream-pivot; the King-substance walks the same architecture at the historical-pivot — but the King-substance walks-the-substance against the inner-corruption of the very-leadership the Maccabean-cleansing had-restored. The substance the King-walks-against is not the Antiochene-outer-defilement but the Pharisaic-Sadducean-inner-corruption — the substance Yirmeyahu (Jeremiah) 7:11 had-named at the First-Temple-pivot when the leadership-substance trusted-in-the-Temple while-walking-against the covenant. The wisdom-stream-substance and the gospel-substance walk the same architecture at-two-different-pivots.'),

  ('canon', 'matthew', 21, 13, 'apocrypha', 'ecclesiasticus', 35, 12,
   '*Do not think to corrupt with gifts; for such he will not receive: and trust not to unrighteous sacrifices; for Yahuah (God) is judge, and with him is no respect of persons.* Sirach (Ecclesiasticus) 35:12 names the wisdom-stream''s direct verbal-anchor against the substance of the monetization-substance the King-overturns-the-tables-of at the temple-cleansing-pericope. The framework reads the verse against Matt 21:13''s *my house shall be called the house of prayer; but ye have made it a den of thieves.* The wisdom-stream-substance the Sirach 35 passage walks names the substance the Father-substance does-not-receive — the substance-of-the-gift-meant-to-corrupt + the substance-of-the-unrighteous-sacrifice. The substance the King-walks-against at the Court-of-the-goyim is the substance the wisdom-stream had-named at the substance-of-corrupt-gifts — the leadership-substance has-monetized the Father''s-house and-trusts-in-the-substance-of-the-unrighteous-sacrifice while-walking-against the substance the Father''s-house was-meant-for. The wisdom-stream and the gospel cohere at the substance-of-the-Father-not-receiving the substance of the corrupt-gifts-of-the-leadership.'),

  ('canon', 'matthew', 21, 13, 'apocrypha', '1-maccabees', 4, 46,
   '*And laid up the stones in the mountain of the temple in a convenient place, until there should come a prophet to shew what should be done with them.* 1 Maccabees 4:46 names THE direct wisdom-stream verbal-anchor for the prophet-yet-to-come substance the King-walks-out at the temple-cleansing-pericope. The framework reads the verse against Matt 21:13''s King-citing the prophet Yirmeyahu (Jeremiah) 7:11 + the multitude''s-confession at Matt 21:11 (*the prophet of Natsareth (Nazareth) of Galil (Galilee)*). The wisdom-stream-substance had-named the prophet-yet-to-come the wisdom-stream-substance did-not-yet-have-the-substance-of; the wisdom-stream-substance left the stones-of-the-defiled-altar laid-up-in-the-temple-mountain *until there should come a prophet to shew what should be done with them.* The substance the wisdom-stream had-named the substance-of-waiting-for is the substance the King walks-into at the temple-cleansing-pericope — the prophet has come; the substance the wisdom-stream-substance had-not-yet-named has-arrived-at the substance-of-the-Father''s-house. The substance is-substantial — the wisdom-stream-substance had-laid the substance-of-anticipation for the prophet-to-come; the King-walks the substance-of-the-prophet-arrived.'),

  -- Thread 3: leaves-without-fruit-judged-in-wisdom-of-solomon-sirach-and-1-enoch
  ('canon', 'matthew', 21, 19, 'apocrypha', 'the-wisdom-of-solomon', 4, 4,
   '*For though they flourish in branches for a time; yet standing not last, they shall be shaken with the wind, and through the force of winds they shall be rooted out.* Wisdom of Solomon 4:4 names the wisdom-stream''s direct verbal-anchor for the flourishing-in-branches-for-a-time-but-standing-not-last substance. The framework reads the verse against Matt 21:19''s *he saw a fig tree in the way, he came to it, and found nothing thereon, but leaves only.* The wisdom-stream-substance the Wisdom of Solomon 4 passage walks is the substance-of-the-ungodly-substance''s-branches that-flourish-for-a-time but-have-no-standing-because-the-root-is-not-there. The substance the King-walks-against at the fig-tree-substance is the same substance the wisdom-stream had-named — the leaves-flourishing-without-the-fruit-substance the leadership-substance walks. The wisdom-stream and the gospel cohere at the substance-of-the-leaves-without-the-fruit-substance — the substance is-not-the-substance-of-the-people-of-Yashar''el (Israel)-categorically per the framework''s system-not-people-posture; the substance is the substance of the Pharisaic-Sadducean-leadership-substance the King-walks-against throughout the gospel.'),

  ('canon', 'matthew', 21, 19, 'apocrypha', 'the-wisdom-of-solomon', 4, 5,
   '*The imperfect branches shall be broken off, their fruit unprofitable, not ripe to eat, yes, meet for nothing.* Wisdom of Solomon 4:5 names THE direct wisdom-stream verbal-anchor for the imperfect-branches-broken-off-and-the-fruit-unprofitable substance the cursed-fig-tree-substance walks. The framework reads the verse against Matt 21:19''s *let no fruit grow on thee henceforward for ever. And presently the fig tree withered away.* The substance the wisdom-stream names at Wisdom of Solomon 4:5 walks the same substance the King-walks-against at the fig-tree-substance — the imperfect-branches-substance that-bears-no-fruit-substance is-broken-off-substance, the fruit-substance that-is-unprofitable-substance is *meet for nothing.* The substance the King-walks at the fig-tree-substance is the substantial-prophetic-action against the Pharisaic-Sadducean leadership-substance the wisdom-stream-substance had-named the architecture-of at-the-prior-pivot. The framework reads the verse in continuity with Matt 7:15-20''s fruit-test-substance + Matt 23''s seven-woes-against-the-scribes-and-Pharisees the King will-deliver in-this-very-week.'),

  ('canon', 'matthew', 21, 19, 'apocrypha', 'ecclesiasticus', 23, 25,
   '*Her children shall not take root, and her branches shall bring forth no fruit.* Sirach (Ecclesiasticus) 23:25 names the wisdom-stream''s direct articulation of the no-root-and-no-fruit substance the cursed-fig-tree-substance walks. The framework reads the verse against Matt 21:19''s *let no fruit grow on thee henceforward for ever.* The Sirach 23 passage walks the substance of the substance-that-walks-against-the-covenant — the children-substance that-shall-not-take-root and the branches-substance that-shall-bring-forth-no-fruit. The substance the King-walks-against at the fig-tree-substance is the same architectural-substance — the leadership-substance has-walked-against the covenant-substance the Father planted-and-hedged-and-tended-for-fruit per the Yeshayahu (Isaiah) 5:1-7 vineyard-substance the King will-walk-out at the wicked-husbandmen-parable at vv.33-46. The leaves-without-the-fruit-substance has-no-root and-shall-bring-forth-no-fruit; the substance is-substantial — the architectural-substance has-walked-against the substance the Father-had-given-the-leadership-to-tend.'),

  ('canon', 'matthew', 21, 19, 'enoch', '1-enoch', 89, 35,
   '*And after that those beasts and birds began to attack the sheep, and to devour them, and to tear them in pieces. And the Lord of the sheep was silent, and the beasts and birds devoured the sheep, and the sheep were scattered.* 1 Enoch 89:35 names the Animal-Apocalypse''s articulation of the consequences-on-the-flock when the unfruitful-leadership-substance walks. The framework reads the verse against Matt 21:19''s fig-tree-cursed-without-fruit substance. The Animal-Apocalypse-substance the wisdom-stream walks at the substance-of-the-sheep-being-devoured-and-scattered is the substance the unfruitful-leadership-substance the King-walks-against carries-the-consequences-of — the sheep-substance is devoured-and-scattered when the leadership-substance walks-against-the-covenant. The substance is-substantial — the framework reads the verse in continuity with Yechezk''el (Ezekiel) 34''s *woe be to the shepherds of Yashar''el (Israel) that do feed themselves! should not the shepherds feed the flocks?* substance the prophet had-named the architecture-of, and the substance the King-himself-walks at John 10:11-16 (*I am the good shepherd: the good shepherd giveth his life for the sheep*) walks-the-substance-against. The unfruitful-leadership-substance produces-the-scattered-flock; the King-substance comes-to-gather the scattered-substance the unfruitful-leadership had-scattered.'),

  -- Thread 4: parable-of-the-two-sons-and-the-wisdom-streams-repentance-and-hypocrisy-architecture
  ('canon', 'matthew', 21, 29, 'apocrypha', 'ecclesiasticus', 17, 24,
   '*But to them that repent, he granted them return, and comforted those that failed in patience.* Sirach (Ecclesiasticus) 17:24 names the wisdom-stream''s direct verbal-anchor for the *to-them-that-repent-he-granted-them-return* substance the first-son-substance walks at the parable. The framework reads the verse against Matt 21:29''s *I will not: but afterward he repented, and went.* The wisdom-stream-substance the Sirach 17:24 passage walks is the substance-of-the-Father-granting-return-to-the-substance-of-repentance — the substance the first-son-substance walks at the parable-substance. The substance the King-walks at the parable is the substantial-parabolic-substance for-the-substance the wisdom-stream had-named — the substance-of-saying-no-by-the-substance-walked but-afterward-repenting-and-doing is the substance the Father-grants-return-to. The publicans-and-harlots-substance the King names at v.31 walk the substance the wisdom-stream had-named at Sirach 17:24 — afterward-repenting-and-walking-the-substance the substance the system-substance had-categorically-excluded-them-from.'),

  ('canon', 'matthew', 21, 30, 'apocrypha', 'ecclesiasticus', 1, 28,
   '*Distrust not the fear of Yahuah (God) when you are poor: and come not to him with a double heart.* Sirach (Ecclesiasticus) 1:28 names the wisdom-stream''s direct verbal-anchor for the *double-heart* substance the second-son-substance walks at the parable. The framework reads the verse against Matt 21:30''s *I go, sir: and went not.* The wisdom-stream-substance the Sirach 1:28 passage walks names the substance the Father-substance does-not-receive — the substance-of-coming-to-him-with-a-double-heart, the substance-of-saying-yes-by-the-mouth-but-walking-no-by-the-substance. The second-son-substance at the parable walks the substance the wisdom-stream had-named at the substance-of-the-double-heart — the substance-of-the-mouth-saying-one-thing-and-the-substance-walking-another. The framework reads the substance in continuity with Matt 7:21-23''s *not every one that saith unto me, Lord, Lord* substance + James 1:8''s *double minded man is unstable in all his ways* substance + 1 John 2:3-4''s *he that saith, I know him, and keepeth not his commandments, is a liar* substance — the substance of the doing-of-the-Father''s-will against the substance of the saying-yes-without-doing.'),

  ('canon', 'matthew', 21, 30, 'apocrypha', 'ecclesiasticus', 1, 29,
   '*Be not an hypocrite in the sight of men, and take good heed what you speak.* Sirach (Ecclesiasticus) 1:29 names the wisdom-stream''s direct articulation of the be-not-a-hypocrite-in-the-sight-of-men substance the second-son-substance walks. The framework reads the verse against Matt 21:30''s *I go, sir: and went not* + the chief-priests-and-elders-substance the King-walks-against. The wisdom-stream-substance the Sirach 1:29 passage names the substance-of-the-hypocrite — the Greek *hypokritēs* the King uses against the Pharisees throughout the gospel (Matt 6:2, 6:5, 6:16, 15:7, 22:18, 23:13-29, 24:51). The substance the wisdom-stream had-named at Sirach 1:29 is the substance the King-walks-against at the substance of the chief-priests-and-elders walking-the-second-son''s-substance — saying-yes-with-the-mouth at the Pharisaic-righteousness-substance but-walking-no at the substance the Father had-laid at the Yochanan (John)-substance. The substance is-substantial — the wisdom-stream and the gospel cohere at the substance-of-the-hypocrite the Father-does-not-receive.'),

  ('canon', 'matthew', 21, 32, 'apocrypha', 'ecclesiasticus', 21, 1,
   '*My son, have you sinned? do so no more, but ask pardon for your former sins. Flee from sin as from the face of a serpent.* Sirach (Ecclesiasticus) 21:1 names the wisdom-stream''s direct articulation of the *ask-pardon-for-your-former-sins* substance the Yochanan (John)-baptism-substance walked-out at the wilderness-pericope. The framework reads the verse against Matt 21:32''s *Yochanan (John) came unto you in the way of righteousness, and ye believed him not: but the publicans and the harlots believed him.* The wisdom-stream-substance the Sirach 21:1 passage walks names the substance the publicans-and-harlots-substance walked at the Yochanan-substance — the substance of *do so no more* and *ask pardon for your former sins* the Yochanan-substance was the prophetic-articulation-of at the wilderness-pericope. The substance the chief-priests-and-elders-substance refused-to-walk is the substance the wisdom-stream had-named the architecture-of — the substance of *flee from sin* + *do so no more* + *ask pardon*. The first-son-substance walks the wisdom-stream-substance the wisdom-stream had-named; the second-son-substance walks-the-substance-of-saying-yes-without-the-substance-walked.'),

  ('canon', 'matthew', 21, 32, 'apocrypha', '2-esdras', 9, 11,
   '*And they that have loathed my law, while they had yet liberty, and, when as yet place of repentance was open to them, understood not, but despised it.* 2 Esdras 9:11 names the wisdom-stream''s direct verbal-anchor for the substance-of-the-leadership-substance despising-the-substance-of-repentance the Father had opened to them. The framework reads the verse against Matt 21:32''s *and ye, when ye had seen it, did not repent afterward, that ye might believe him.* The wisdom-stream-substance the 2 Esdras 9:11 passage walks is the substance-of-the-substance-of-the-leadership''s-substance refusing-to-walk-the-substance-of-repentance when-the-place-of-repentance-was-open. The substance is-substantial — the Yochanan (John)-substance was-the-place-of-repentance-open-to-the-substance-of-the-leadership at the wilderness-pericope; the substance-of-the-leadership-substance despised-the-substance-of-repentance the substance-of-the-Father had-opened-to-them. The wisdom-stream and the gospel cohere at the substance-of-the-leadership''s-substance walking the second-son''s-substance — saying-yes-by-the-substance-of-Pharisaic-righteousness but-walking-not-the-substance-of-repentance the substance-of-the-Father had-opened.'),

  -- Thread 5: wicked-husbandmen-prophets-slain-house-desolate-and-the-tribes-gathered-as-from-the-beginning (FRAMEWORK-MAJOR)
  ('canon', 'matthew', 21, 35, 'apocrypha', '2-esdras', 1, 32,
   '*I sent to you my servants the prophets, whom you have taken and slain, and torn their bodies in pieces, whose blood I will require of your hands, says Yahuah (God).* 2 Esdras 1:32 names THE direct wisdom-stream verbal-anchor for the servants-the-prophets-taken-and-slain substance the parable-of-the-wicked-husbandmen walks-out at vv.34-36. The framework reads the verse against Matt 21:35''s *and the husbandmen took his servants, and beat one, and killed another, and stoned another.* The wisdom-stream-substance the 2 Esdras 1:32 passage walks names the same architectural-substance the parable-substance walks-out — the substance of *my servants the prophets* the Father-substance sends + the substance of the leadership-substance taking-and-slaying-and-tearing-the-bodies-in-pieces. The Tanakh-pattern of prophet-killing the King-walks-out at the parable is named at the wisdom-stream-substance at 2 Esdras 1:32 directly. The Father''s-substance-of-requiring-the-blood-of-the-prophets is the substance the apostolic-Matt-23:35 substance will-walk-out at the substance-of *the blood of all the prophets, which was shed from the foundation of the world, may be required of this generation.* The wisdom-stream and the gospel cohere at the substance-of-the-leadership''s-substance walking-the-substance-of-the-prophet-killing-pattern.'),

  ('canon', 'matthew', 21, 39, 'apocrypha', '2-esdras', 1, 33,
   '*Thus says the Almighty Yahuah (God), Your house is desolate, I will cast you out as the wind does stubble.* 2 Esdras 1:33 names the wisdom-stream''s direct verbal-anchor for the house-desolate substance the consequence-of-the-killing-of-the-Son walks-into at the parable. The framework reads the verse against Matt 21:39''s *and they caught him, and cast him out of the vineyard, and slew him* + Matt 21:41''s *he will miserably destroy those wicked men* + the Olivet-discourse-substance at Matthew 24:1-2 (*there shall not be left here one stone upon another, that shall not be thrown down*). The wisdom-stream-substance the 2 Esdras 1:33 passage walks names the substance the substance-of-the-leadership-substance''s-walking-against the Father-substance carries-the-consequence-of — *your house is desolate.* The substance is-substantial — the killing-of-the-son-substance the wicked-husbandmen walk-into at v.39 walks-into the substance the wisdom-stream had-named the architecture-of at *your house is desolate.* The Tanakh-pattern of *I never knew you: depart from me, ye that work iniquity* at Matt 7:23 + the *behold, your house is left unto you desolate* at Matt 23:38 cohere with the wisdom-stream-substance at the substance the leadership-substance''s-walking-against the Father carries the consequence of.'),

  ('canon', 'matthew', 21, 41, 'enoch', '1-enoch', 89, 45,
   '*And the shepherds who had not fed the sheep were judged, and cast into the same fiery abyss with the beasts.* 1 Enoch 89:45 names the Animal-Apocalypse''s direct verbal-anchor for the leadership-judgment-substance the *he will miserably destroy those wicked men* at v.41 walks-into. The framework reads the verse against Matt 21:41''s system-substance answering-correctly at-the-parable-substance-level — *he will miserably destroy those wicked men, and will let out his vineyard unto other husbandmen, which shall render him the fruits in their seasons.* The Animal-Apocalypse-substance the 1 Enoch 89:45 passage walks names the substance the Father-substance walks-against the unfaithful-shepherds the wisdom-stream-substance had-named the architecture-of — the shepherds who-had-not-fed-the-sheep-substance receive-the-substance-of-being-judged-and-cast-into-the-fiery-abyss-with-the-beasts. The substance is-substantial — the framework reads the verse in continuity with Yechezk''el (Ezekiel) 34''s *woe be to the shepherds of Yashar''el (Israel) that do feed themselves!* + Yirmeyahu (Jeremiah) 23''s *woe be unto the pastors that destroy and scatter the sheep of my pasture!* — the Tanakh-prophets had-named the substance, the wisdom-stream-substance had-walked-the-substance at the Animal-Apocalypse-pivot, and the King-substance walks-the-same-substance at the wicked-husbandmen-parable-substance. The substance is the leadership-substance, NOT the people-of-Yashar''el (Israel) categorically.'),

  ('canon', 'matthew', 21, 43, 'apocrypha', 'ecclesiasticus', 36, 11,
   '*Gather all the tribes of Ya''aqov (Jacob) together, and inherit you them, as from the beginning.* Sirach (Ecclesiasticus) 36:11 names THE direct wisdom-stream verbal-anchor for the gather-all-the-tribes-of-Ya''aqov substance the chapter-pivot at v.43 walks-into per Red Line #11''s ingathering-of-the-paternal-blood-remnant-of-all-twelve-tribes architecture. **FRAMEWORK-MAJOR.** The framework reads the verse against Matt 21:43''s *the kingdom of Elohim (God) shall be taken from you, and given to a nation bringing forth the fruits thereof.* The wisdom-stream-substance the Sirach 36:11 passage walks names the substance-of-the-Father-gathering-all-twelve-tribes-of-Ya''aqov-as-the-substance-of-the-inheritance the substance-of-the-beginning had-laid. The *nation* (Greek *ethnos*, SINGULAR-not-plural) the King names at v.43 IS this gathered-bringing-forth-fruit-remnant of the twelve-tribes-of-Ya''aqov the wisdom-stream-substance had-prayed-the-Father-for. The framework rules out THREE inherited readings: (1) the Christian-replacement-theology that-the-categorical-church-replaces-Yashar''el (Israel) collapses the singular-*ethnos* against the wisdom-stream''s-direct-naming of the substance as *all the tribes of Ya''aqov*; (2) the Hebrew-Roots-false-inclusion that-the-Torah-keeping-categorical-anyone replaces-the-current-leadership collapses the paternal-blood-substance the *tribes of Ya''aqov* names by-name-by-tribe; (3) the Reformation-sola-fide-without-fruit that-the-bringing-forth-fruit is-incidental collapses the load-bearing-clause itself. The substance is-substantial — the wisdom-stream had-prayed-the-Father-for the substance the King-walks-out at v.43; the substance the apostolic-witness carries-forward at Matt 19:28''s *twelve thrones, judging the twelve tribes of Yashar''el* + Acts 26:6-7''s *twelve tribes, instantly serving Elohim (God) day and night, hope to come* + James 1:1''s *to the twelve tribes which are scattered abroad* + Revelation 7:4-8''s twelve-tribes-sealed + Revelation 21:12-14''s twelve-gates-of-the-twelve-tribes + Ephesians 2:20''s apostolic-foundation + 1 Peter 2:9-10''s holy-*ethnos* singular addressed to the *strangers scattered* — IS the substance the wisdom-stream had-named, the substance the framework reads at-the-Red-Line-#11-load-bearing-anchor.')

)
INSERT INTO cross_references (source_verse_id, target_verse_id, source, note, tier_required)
SELECT sv.verse_id, tv.verse_id, 'manual', i.note, 'extras'::content_tier
  FROM input i
  JOIN _s155_xref_lookup sv ON sv.edition_slug   = i.src_edition
                           AND sv.book_slug      = i.src_slug
                           AND sv.chapter_number = i.src_ch
                           AND sv.verse_number   = i.src_v
  JOIN _s155_xref_lookup tv ON tv.edition_slug   = i.tgt_edition
                           AND tv.book_slug      = i.tgt_slug
                           AND tv.chapter_number = i.tgt_ch
                           AND tv.verse_number   = i.tgt_v
 WHERE sv.verse_id <> tv.verse_id
ON CONFLICT (source_verse_id, target_verse_id, source) DO NOTHING;

