-- Thread 1 (sort 327): davidic-messianic-king-meek-on-the-foal-in-testaments-xii-and-2-maccabees
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'davidic-messianic-king-meek-on-the-foal-in-testaments-xii-and-2-maccabees',
       'The Davidic-Messianic-King meek-on-the-foal at the entry — Testaments of the XII Patriarchs (Yahudah ch 15), 2 Maccabees 10:7''s branches-and-palms-and-psalms, and Sirach 36:14''s glory-filling-Tsion',
       'Matt 21:1-11''s triumphal-entry-substance — the King-of-Yashar''el (Israel) coming-to-his-city on the foal-of-an-ass per Zecharyah (Zechariah) 9:9; the multitudes crying *Hoshia-na (Hosanna) to the Son of David: Blessed is he that cometh in the name of Yahuah (the LORD)* from Tehillim (Psalm) 118:25-26''s pilgrim-Hallel; the branches-and-garments strewn in the way; the city''s *Who is this?* answered by the multitude''s *the prophet of Natsareth (Nazareth) of Galil (Galilee)* — read against the wisdom-stream''s direct articulation of the Davidic-Messianic-King substance the wisdom-stream-corpus had carried for centuries before the gospel-pivot. Four moves: Test. Yahudah (Judah) ch 15 v.5 (= testaments-xii ch 38 in the Charles vol 2 flat-chapter scheme) names THE direct verbal-anchor for the sceptre-of-the-kingdom-shining-forth + the stem-arising-from-the-root substance (*then shall the sceptre of my kingdom shine forth ; and from your root shall arise a stem*) — the wisdom-stream''s articulation of the Tanakh-Netser-Branch-substance per Yeshayahu (Isaiah) 11:1 the King-of-the-tribe-of-Yahudah (Judah) walks-out at the entry; Test. Yahudah ch 15 v.6 names the rod-of-righteousness-substance — *to judge and to save all that call upon Yahuah (Lord)* — the substance the marginalized-substance had-been-crying *Son of David* at and the multitudes now-walk-publicly at the entry-substance; 2 Maccabees 10:7 names THE direct verbal-anchor for the branches-and-palms-and-psalms substance (*they bare branches, and fair boughs, and palms also, and sang psalms*) the Hanukkah-temple-rededication-ceremony walked at the wisdom-stream-pivot — the multitudes at the entry walk the same substance at the historical-pivot the chapter immediately-walks-into the temple-cleansing-substance the Hanukkah-substance had-walked-the-architectural-parallel-of; Sirach (Ecclesiasticus) 36:14 names the wisdom-stream''s prayer-for-the-glory-to-fill-Tsion (Zion) substance (*fill Sion with your unspeakable oracles, and your people with your glory*) the King''s-arriving-at-the-city walks-out (the Greek *eseisthē* the Matthean account uses for *all the city was moved* at v.10 carries the same root the Matt 27:51 earthquake-substance and the Matt 28:2 resurrection-earthquake-substance carry — the wisdom-stream had-named the Father''s-glory-arriving-at-Tsion as the substance-that-fills-Tsion; the gospel walks the same substance at the King-arriving-into-the-shaken-city). The framework reads the substance per Red Line #7 + Red Line #11 — the *all that call upon Yahuah (Lord)* in Test. Yahudah carries the wisdom-stream-convention of *Gentiles* as the scattered-seed-of-Yashar''el (Israel) living-as-Gentiles-among-the-nations per the apostolic-Paul-letters-convention, NOT the categorical-Three-Categories-#3-nations replacing-Yashar''el; the meekness-substance is the Greek *praus* / Hebrew *ani* substance per Matthew 5:5 and Matthew 11:29 the King-of-Yashar''el walks-against the natural-kingdoms''-substance-of-domination per Matthew 20:25.',
       sv.verse_id, ev.verse_id, 'complete_study', 327
  FROM _s155_xref_lookup sv, _s155_xref_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 21 AND sv.verse_number = 1
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 21 AND ev.verse_number = 11
ON CONFLICT (slug) DO NOTHING;

-- Thread 2 (sort 328): temple-cleansing-and-the-maccabean-rededication-architecture
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'temple-cleansing-and-the-maccabean-rededication-architecture',
       'Temple-cleansing and the Maccabean-rededication architecture — 1 Maccabees 4, 2 Maccabees 10, and Sirach 35:12''s do-not-corrupt-with-gifts',
       'Matt 21:12-17''s temple-cleansing-substance — the King-of-Yashar''el (Israel) overturning-the-tables-of-the-moneychangers in the Court-of-the-goyim (Gentiles); the King citing Yeshayahu (Isaiah) 56:7 *my house shall be called the house of prayer* (whose context names the outcasts-of-Yashar''el being-gathered-to-the-holy-mountain — the gathering of the scattered-seed-coming-home per Red Line #7) + Yirmeyahu (Jeremiah) 7:11 *den of thieves* (whose context is one of the Tanakh''s most-substantial Temple-judgment-passages, walking the same substance against the Second-Temple leadership the prophet had walked at the First-Temple); the healing of the blind-and-the-lame in the Temple reversing the rabbinic-substance reading of 2 Samuel 5:8 as a categorical-exclusion; the children-in-the-Temple crying *Hoshia-na (Hosanna) to the Son of David* with the King citing Tehillim (Psalm) 8:2 *out of the mouth of babes and sucklings* — read against the wisdom-stream''s direct articulation of the Maccabean-Hanukkah-temple-cleansing architecture and the wisdom-stream''s direct articulation against the substance of corrupt-gifts. Four moves: 1 Maccabees 4:43 names the wisdom-stream''s direct verbal-anchor for the cleansing-of-the-sanctuary substance (*who cleansed the sanctuary, and bare out the defiled stones into an unclean place*) — the architectural-substance the King-walks-out at the Second-Temple-pivot, with the architectural-parallel running at-two-different-pivots between the Maccabean-cleansing-against-the-Antiochene-outer-defilement and the King''s-cleansing-against-the-Pharisaic-Sadducean-inner-corruption; 2 Maccabees 10:3 names the wisdom-stream''s narration of the Hanukkah-cleansing-followed-by-the-restoration-of-the-sacrifice + the incense + the lights + the shewbread (*having cleansed the temple they made another altar*) — the substance the Father''s-house was-meant-for; Sirach (Ecclesiasticus) 35:12 names THE direct verbal-anchor against the substance of the monetization-substance the King-overturns-the-tables-of (*do not think to corrupt with gifts; for such he will not receive: and trust not to unrighteous sacrifices; for Yahuah (God) is judge, and with him is no respect of persons*) — the wisdom-stream''s direct articulation the King walks-out at the temple-cleansing-substance; 1 Maccabees 4:46 names THE direct verbal-anchor for the prophet-yet-to-come substance (*until there should come a prophet to shew what should be done with them*) — the wisdom-stream-substance had-laid the substance-of-anticipation for the prophet-to-come whom the multitude at v.11 names *the prophet of Natsareth (Nazareth) of Galil (Galilee)* and the King-walks-out at the temple-cleansing-substance carrying-the-substance-of-the-prophet-arrived. The framework reads the substance per the system-not-people-posture — the substance the King-walks-against is the Pharisaic-Sadducean-leadership-substance the wisdom-stream-Sirach-50-substance had-named the Simon-the-high-priest-substance the architectural-parallel-of; the substance is-NOT the people-of-Yashar''el (Israel) categorically.',
       sv.verse_id, ev.verse_id, 'complete_study', 328
  FROM _s155_xref_lookup sv, _s155_xref_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 21 AND sv.verse_number = 12
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 21 AND ev.verse_number = 17
ON CONFLICT (slug) DO NOTHING;

-- Thread 3 (sort 329): leaves-without-fruit-judged-in-wisdom-of-solomon-sirach-and-1-enoch
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'leaves-without-fruit-judged-in-wisdom-of-solomon-sirach-and-1-enoch',
       'Leaves without fruit judged — Wisdom of Solomon 4''s flourish-in-branches-for-a-time, Sirach 23:25''s no-root-no-fruit, and 1 Enoch 89''s consequences-on-the-scattered-flock',
       'Matt 21:18-22''s cursed-fig-tree-substance — the King-of-Yashar''el (Israel) walking the substantial-prophetic-action against the leaves-without-fruit substance the Pharisaic-Sadducean-leadership had-walked; the Tanakh-fig-tree-substance of Hosheia (Hosea) 9:10, Yirmeyahu (Jeremiah) 8:13, Yo''el (Joel) 1:7, and Mikhah (Micah) 7:1 carried-forward as the covenant-fruitfulness-substance the leadership-substance had-corrupted — read against the wisdom-stream''s direct articulation of the unfruitful-branches-substance-judged architecture. Four moves: Wisdom of Solomon 4:4 names the wisdom-stream''s direct verbal-anchor for the flourishing-in-branches-for-a-time-but-standing-not-last substance (*for though they flourish in branches for a time; yet standing not last, they shall be shaken with the wind, and through the force of winds they shall be rooted out*); Wisdom of Solomon 4:5 names THE direct verbal-anchor for the imperfect-branches-broken-off-and-the-fruit-unprofitable substance (*the imperfect branches shall be broken off, their fruit unprofitable, not ripe to eat, yes, meet for nothing*) — the wisdom-stream''s direct articulation of the substance the King-walks-against at the fig-tree-substance; Sirach (Ecclesiasticus) 23:25 names the wisdom-stream''s articulation of the no-root-and-no-fruit substance (*her children shall not take root, and her branches shall bring forth no fruit*); 1 Enoch 89:35 names the Animal-Apocalypse''s articulation of the consequences-on-the-scattered-flock-when-the-unfruitful-leadership-walks (*and the Lord of the sheep was silent, and the beasts and birds devoured the sheep, and the sheep were scattered*). The framework reads the cluster per the framework''s system-not-people-posture — the substance the King-walks-against at the fig-tree-substance is the Pharisaic-Sadducean-leadership-substance the wisdom-stream-corpus and the Animal-Apocalypse-substance had-named the architecture-of; the substance is-NOT the people-of-Yashar''el (Israel) categorically, per the same diagnostic the matt-13-tares, the matt-15-blind-leaders-of-the-blind, and the matt-23-seven-woes hold throughout the gospel. The framework reads the Tanakh-prophets'' shepherd-substance — Yechezk''el (Ezekiel) 34''s *woe be to the shepherds of Yashar''el (Israel) that do feed themselves!* + Yirmeyahu (Jeremiah) 23''s *woe be unto the pastors that destroy and scatter the sheep of my pasture!* — in continuity with the King''s-own-substance at John 10:11-16 (*I am the good shepherd: the good shepherd giveth his life for the sheep*) — the unfruitful-leadership-substance produces-the-scattered-flock; the King-substance comes-to-gather the scattered-substance the unfruitful-leadership had-scattered.',
       sv.verse_id, ev.verse_id, 'complete_study', 329
  FROM _s155_xref_lookup sv, _s155_xref_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 21 AND sv.verse_number = 18
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 21 AND ev.verse_number = 22
ON CONFLICT (slug) DO NOTHING;

-- Thread 4 (sort 330): parable-of-the-two-sons-and-the-wisdom-streams-repentance-and-hypocrisy-architecture
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'parable-of-the-two-sons-and-the-wisdom-streams-repentance-and-hypocrisy-architecture',
       'Parable of the two sons and the wisdom-stream''s repentance-and-hypocrisy architecture — Sirach 17:24, Sirach 1:28-29, Sirach 21:1, and 2 Esdras 9:11',
       'Matt 21:28-32''s parable-of-the-two-sons-substance — the doing-of-the-Father''s-will substance against the saying-yes-without-doing substance; the first-son-substance saying *I will not* (Greek *ou thelō*) and-afterward-repenting-and-going (the publicans-and-harlots walking the substance the Pharisaic-system had-categorically-excluded); the second-son-substance saying *I go, sir* (Greek *egō, kyrie* — the *Lord, Lord* substance per Matthew 7:21) and-walking-not (the chief-priests-and-elders walking the substance of saying-yes-without-doing); the substance directly ties to Matthew 7:21-23 *not every one that saith unto me, Lord, Lord, shall enter into the kingdom of heaven; but he that doeth the will of my Father which is in heaven* and to *Torah-lessness* (Greek *anomia* — Torah-less-walking) the King names — read against the wisdom-stream''s direct articulation of the repentance-and-hypocrisy architecture. Five moves: Sirach (Ecclesiasticus) 17:24 names THE direct verbal-anchor for the *to-them-that-repent-he-granted-them-return* substance (*but to them that repent, he granted them return, and comforted those that failed in patience*) the first-son-substance walks; Sirach (Ecclesiasticus) 1:28 names THE direct verbal-anchor for the *double-heart* substance (*distrust not the fear of Yahuah (God) when you are poor: and come not to him with a double heart*) the second-son-substance walks; Sirach (Ecclesiasticus) 1:29 names the wisdom-stream''s direct articulation of the be-not-a-hypocrite-in-the-sight-of-men substance (*be not an hypocrite in the sight of men, and take good heed what you speak*) — the Greek *hypokritēs* the King uses against the Pharisees throughout the gospel (Matt 6:2, 6:5, 6:16, 15:7, 22:18, 23:13-29, 24:51) the wisdom-stream-substance had-named the architecture-of; Sirach (Ecclesiasticus) 21:1 names the *ask-pardon-for-your-former-sins* substance (*my son, have you sinned? do so no more, but ask pardon for your former sins*) the Yochanan (John)-baptism-substance walked-out at the wilderness-pericope; 2 Esdras 9:11 names the wisdom-stream''s direct verbal-anchor for the leadership-substance''s despising-the-substance-of-repentance the Father-substance-had-opened (*and they that have loathed my law, while they had yet liberty, and, when as yet place of repentance was open to them, understood not, but despised it*) — the substance the chief-priests-and-elders walking-the-second-son''s-substance carries. The framework reads the cluster per Red Line #2 + Red Line #10 + the *Torah-lessness* substance — the substance the wisdom-stream-corpus carries at the substance-of-the-doing-against-the-saying is the substance the apostolic-Paul-letters carry at Romans 2:13 (*not the hearers of the law are just before Elohim (God), but the doers of the law shall be justified*) + the apostolic-James-letter carries throughout (1:22 + 2:14-26) + the apostolic-Yochanan-letter carries at 1 John 2:3-4 (*hereby we do know that we know him, if we keep his commandments*) — the cause-and-effect-of-hearing per Red Line #11 operates at the substance the publicans-and-harlots-substance walked-into-and-the-leadership-substance walked-against.',
       sv.verse_id, ev.verse_id, 'complete_study', 330
  FROM _s155_xref_lookup sv, _s155_xref_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 21 AND sv.verse_number = 28
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 21 AND ev.verse_number = 32
ON CONFLICT (slug) DO NOTHING;

-- Thread 5 (sort 331): wicked-husbandmen-prophets-slain-house-desolate-and-the-tribes-gathered-as-from-the-beginning (FRAMEWORK-MAJOR)
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'wicked-husbandmen-prophets-slain-house-desolate-and-the-tribes-gathered-as-from-the-beginning',
       'The wicked husbandmen — prophets slain, house desolate, corrupt shepherds judged, and the tribes of Ya''aqov (Jacob) gathered as from the beginning (FRAMEWORK-MAJOR)',
       'Matt 21:33-46''s FRAMEWORK-MAJOR parable-of-the-wicked-husbandmen — the Yeshayahu (Isaiah) 5:1-7 vineyard-of-Yahuah Tseva''ot (LORD of hosts) substance walked-out at the leadership-level (the husbandmen are the LEADERSHIP-substance, NOT the people-of-Yashar''el (Israel) categorically); the servants-substance is the prophets-substance the Tanakh names; the killing-and-stoning is the Tanakh-prophet-killing-pattern; the *last of all he sent unto them his son* substance is the King''s-walking-toward-the-cross; the King citing Tehillim (Psalm) 118:22-23 *the stone which the builders rejected*; the chapter-pivot at v.43 — *the kingdom of Elohim (God) shall be taken from you, and given to a nation bringing forth the fruits thereof* — the framework-MAJOR-substance for the kingdom-stewardship-transferred-from-the-current-leadership-stewards-of-Yahudah (Judah) to-the-bringing-forth-fruit-remnant-of-the-gathering-of-the-scattered-seed-of-both-houses-of-Yashar''el (Israel), with the Greek *ethnos* SINGULAR-not-plural locking the reading against the inherited-Christian-replacement-theology collapse — read against the wisdom-stream''s direct articulations of (a) the prophets-slain substance + (b) the house-desolate substance + (c) the corrupt-shepherds-judged substance + (d) the gather-all-the-tribes-of-Ya''aqov-as-from-the-beginning substance the v.43 framework-MAJOR-pivot walks-into. Four moves: 2 Esdras 1:32 names THE direct verbal-anchor for the servants-the-prophets-taken-and-slain substance (*I sent to you my servants the prophets, whom you have taken and slain, and torn their bodies in pieces, whose blood I will require of your hands*) the parable walks-out at vv.34-36; 2 Esdras 1:33 names THE direct verbal-anchor for the house-desolate substance (*your house is desolate, I will cast you out as the wind does stubble*) the consequence-of-the-killing-of-the-Son at v.39 walks-into per the Olivet-discourse-substance at Matthew 24:1-2; 1 Enoch 89:45 names the Animal-Apocalypse''s direct verbal-anchor for the leadership-judgment-substance (*the shepherds who had not fed the sheep were judged, and cast into the same fiery abyss with the beasts*) the *he will miserably destroy those wicked men* at v.41 walks-into; Sirach (Ecclesiasticus) 36:11 names THE direct wisdom-stream verbal-anchor for the gather-all-the-tribes-of-Ya''aqov substance (*gather all the tribes of Ya''aqov (Jacob) together, and inherit you them, as from the beginning*) the chapter-pivot at v.43 walks-into per Red Line #11''s ingathering-of-the-paternal-blood-remnant-of-all-twelve-tribes architecture. The framework reads the v.43 *nation* (Greek *ethnos*, SINGULAR-not-plural) as the gathered-bringing-forth-fruit-remnant of the twelve-tribes-of-Ya''aqov the wisdom-stream-Sirach-36:11 substance had-prayed-the-Father-for, NOT the categorical-displacement of Yashar''el (Israel) by the church. The framework rules out THREE inherited readings of v.43: (1) the Christian-replacement-theology that-the-categorical-church-replaces-Yashar''el collapses the singular-*ethnos* against the wisdom-stream''s-direct-naming of the substance as *all the tribes of Ya''aqov*; (2) the Hebrew-Roots-false-inclusion that-the-Torah-keeping-categorical-anyone replaces-the-current-leadership collapses the paternal-blood-substance the *tribes of Ya''aqov* names by-name-by-tribe per Red Line #3; (3) the Reformation-sola-fide-without-fruit that-the-bringing-forth-fruit is-incidental collapses the load-bearing-clause itself — the bringing-forth-fruit-substance is the Spirit-empowered-heart-Torah-walking substance per Yirmeyahu (Jeremiah) 31:31-34 + Yechezk''el (Ezekiel) 36:26-27 + James 2:14-26''s faith-without-works-is-dead substance. The apostolic-witness''s twelve-tribes-restoration architecture — Matt 19:28''s *twelve thrones, judging the twelve tribes of Yashar''el* + Acts 26:6-7''s *twelve tribes, instantly serving Elohim (God) day and night, hope to come* + James 1:1''s *to the twelve tribes which are scattered abroad* + Revelation 7:4-8''s twelve-tribes-sealed + Revelation 21:12-14''s twelve-gates-of-the-twelve-tribes + Ephesians 2:20''s apostolic-foundation + 1 Peter 2:9-10''s holy-*ethnos* singular addressed to the *strangers scattered* — IS the substance the wisdom-stream had-named, the substance the framework reads at-the-Red-Line-#11-load-bearing-anchor.',
       sv.verse_id, ev.verse_id, 'complete_study', 331
  FROM _s155_xref_lookup sv, _s155_xref_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 21 AND sv.verse_number = 33
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 21 AND ev.verse_number = 46
ON CONFLICT (slug) DO NOTHING;

