INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note)
SELECT t.id, x.id, 4, 'Sirach (Ecclesiasticus) 36:14 — *fill Sion (Zion) with your unspeakable oracles, and your people with your glory.* The wisdom-stream''s prayer-for-the-glory-to-fill-Tsion the King''s-arriving-at-the-city walks-out at Matt 21:9-10. The Greek *eseisthē* the Matthean account uses for *all the city was moved* carries the same root the Matt 27:51 crucifixion-earthquake and the Matt 28:2 resurrection-earthquake carry — the wisdom-stream had-named the Father''s-glory-arriving-at-Tsion as the substance-that-fills-Tsion; the gospel walks the same substance at the King-arriving-into-the-shaken-city.'
