-- ---------------------------------------------------------------------
-- Verification block.
-- ---------------------------------------------------------------------
DO $verify$
DECLARE
  v_xref_inserted INT;
  v_thread_inserted INT;
  v_member_inserted INT;
BEGIN
  SELECT count(*) INTO v_xref_inserted FROM cross_references x
    JOIN _s155_xref_lookup sv ON sv.verse_id = x.source_verse_id
   WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 21
     AND x.tier_required = 'extras' AND x.source = 'manual';

  SELECT count(*) INTO v_thread_inserted FROM cross_reference_threads
   WHERE slug IN (
     'davidic-messianic-king-meek-on-the-foal-in-testaments-xii-and-2-maccabees',
     'temple-cleansing-and-the-maccabean-rededication-architecture',
     'leaves-without-fruit-judged-in-wisdom-of-solomon-sirach-and-1-enoch',
     'parable-of-the-two-sons-and-the-wisdom-streams-repentance-and-hypocrisy-architecture',
     'wicked-husbandmen-prophets-slain-house-desolate-and-the-tribes-gathered-as-from-the-beginning'
   );

  SELECT count(*) INTO v_member_inserted
    FROM cross_reference_thread_members m
    JOIN cross_reference_threads t ON t.id = m.thread_id
   WHERE t.slug IN (
     'davidic-messianic-king-meek-on-the-foal-in-testaments-xii-and-2-maccabees',
     'temple-cleansing-and-the-maccabean-rededication-architecture',
     'leaves-without-fruit-judged-in-wisdom-of-solomon-sirach-and-1-enoch',
     'parable-of-the-two-sons-and-the-wisdom-streams-repentance-and-hypocrisy-architecture',
     'wicked-husbandmen-prophets-slain-house-desolate-and-the-tribes-gathered-as-from-the-beginning'
   );

  RAISE NOTICE 'S155 Matt 21 verify: extras xrefs from canon/matthew/21 = %, threads = %, members = %',
    v_xref_inserted, v_thread_inserted, v_member_inserted;

  IF v_thread_inserted <> 5 THEN
    RAISE EXCEPTION 'Expected 5 threads inserted; got %', v_thread_inserted;
  END IF;
  IF v_xref_inserted < 21 THEN
    RAISE EXCEPTION 'Expected at least 21 Matt-21 extras xrefs; got %', v_xref_inserted;
  END IF;
  IF v_member_inserted < 21 THEN
    RAISE EXCEPTION 'Expected at least 21 thread members; got %', v_member_inserted;
  END IF;
END;
$verify$;

COMMIT;
